let fontPromise;
const tick=()=>new Promise(resolve=>setTimeout(resolve,0));
export function checkAbort(signal){if(signal?.aborted)throw new DOMException('أُلغي التجهيز. لم يتغير المشروع.','AbortError')}
async function ensureFont(){if(!fontPromise)fontPromise=(async()=>{const face=new FontFace('RasmInk',`url(${new URL('./ink-arabic.woff',import.meta.url).href})`,{weight:'700'});await face.load();document.fonts.add(face);return face})().catch(error=>{fontPromise=null;throw error});return fontPromise}
function canvas(){return Object.assign(document.createElement('canvas'),{width:960,height:540})}
async function image(svg,signal){checkAbort(signal);const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));try{const img=new Image();img.src=url;await img.decode();checkAbort(signal);return img}finally{URL.revokeObjectURL(url)}}
async function drawLayer(context,scene,layer,signal){context.clearRect(0,0,960,540);if(layer.kind==='text'){context.save();context.scale(.75,.75);context.fillStyle=layer.color;context.textAlign='center';context.direction='rtl';context.textBaseline='alphabetic';context.font=`700 ${layer.size}px RasmInk`;const width=context.measureText(layer.text).width;if(width>layer.maxWidth)context.font=`700 ${layer.size*layer.maxWidth/width}px RasmInk`;context.fillText(layer.text,640,layer.y);context.restore()}else{const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="1280" height="720" viewBox="0 0 1280 720"><defs>${scene.defs}</defs>${layer.body}</svg>`;context.drawImage(await image(svg,signal),0,0,960,540)}}
export async function prepareStory(descriptors,host,{signal,onProgress}){checkAbort(signal);await ensureFont();checkAbort(signal);const prepared=[],checks=[];const count=descriptors.reduce((n,s)=>n+s.layers.length+2,0);let done=0;
 for(const desc of descriptors){checkAbort(signal);const source=canvas(),paint=source.getContext('2d'),maskCanvas=canvas(),mask=maskCanvas.getContext('2d',{willReadFrequently:true}),owners=new Uint16Array(960*540);paint.fillStyle='white';paint.fillRect(0,0,960,540);
  for(const [index,layer]of desc.layers.entries()){checkAbort(signal);await drawLayer(mask,desc,layer,signal);paint.drawImage(maskCanvas,0,0);const alpha=mask.getImageData(0,0,960,540).data;for(let pixel=0;pixel<owners.length;pixel++)if(alpha[pixel*4+3])owners[pixel]=index+1;onProgress('رسم '+desc.title,++done,count);await tick()}
  checkAbort(signal);const scene=await host.analyze(source,desc.title);checkAbort(signal);Object.assign(scene,host.defaults(),{name:desc.title,duration:desc.duration,speed:1,hold:30,sourceHand:'clean',tone:4,transition:'cut',elementDirection:'rtl',zones:[],revealMode:'direct',mode:'original'});const labels=scene.engineAnalysisV2.rasterLabels;if(scene.src.width!==960||scene.src.height!==540)throw Error('اختلفت أبعاد المشهد. لم يتغير المشروع.');let foreground=0,unassigned=0;const used=new Set();for(let p=0;p<owners.length;p++){if(!labels[p])owners[p]=0;else{foreground++;if(!owners[p])unassigned++;else used.add(owners[p])}}
  if(unassigned)throw Error('تعذّر إسناد كل بكسلات المشهد إلى عناصره. لم يتغير المشروع.');const items=desc.layers.map((layer,index)=>({id:desc.id+'-'+layer.id,key:index+1,name:layer.label.slice(0,120),duration:layer.weight||1})).filter(item=>used.has(item.key));const state={version:1,width:960,height:540,revision:1,nextKey:desc.layers.length+1,items,owners};scene.elementDocument=new host.core.ElementDocument(960,540,labels,state).snapshot;onProgress('ترتيب عناصر '+desc.title,++done,count);await host.plan(scene);checkAbort(signal);await host.prepare(scene);checkAbort(signal);onProgress('جاهز: '+desc.title,++done,count);prepared.push(scene);checks.push({id:desc.id,elements:items.length,foreground,unassigned});await tick();maskCanvas.width=maskCanvas.height=1;
 }
 return {scenes:prepared,checks};}
